export const ExponentialLoad = zod.object({
  "id": zod.int().describe('Unique integer identifier for this component.'),
  "name": zod.string().describe('Name of the component. Components of the same type (e.g., `PowerLoad`) must have unique names, but components of different types (e.g., `PowerLoad` and `ACBus`) can have the same name.'),
  "available": zod.boolean().describe('Indicator of whether the component is connected and online (`true`) or disconnected, offline, or down (`false`). Unavailable components are excluded during simulations.'),
  "bus": zod.int().describe('ID of the bus that this component is connected to.'),
  "active_power": zod.number().describe('Active power coefficient, P0. Units: per power_units — NATURAL_UNITS: MW, COMPONENT_BASE: pu .'),
  "reactive_power": zod.number().describe('Reactive power coefficient, Q0. Units: per power_units — NATURAL_UNITS: MVAr, COMPONENT_BASE: pu .'),
  "alpha": zod.number().describe('Exponent relating voltage dependency for active power. 0 = constant power only, 1 = constant current only, and 2 = constant impedance only.'),
  "beta": zod.number().describe('Exponent relating voltage dependency for reactive power. 0 = constant power only, 1 = constant current only, and 2 = constant impedance only.'),
  "base_power": zod.number().describe('Base power of the unit for per unitization. Units: MVA.'),
  "power_units": zod.enum(['COMPONENT_BASE', 'NATURAL_UNITS']).describe('Unit basis a stored value is expressed in. COMPONENT_BASE: per-unit against a base the component records itself. NATURAL_UNITS: the quantity\'s own physical unit. No system-wide option: a value per-unitized against a shared base records that base on the component and rides as COMPONENT_BASE. Used in three scopes, each read against its own record rather than a document-wide table: a component\'s own `power_units` (against that component\'s `base_power`), a cost payload\'s own `power_units` (e.g. `CostCurve`, against the owning component\'s `base_power`), and a time series association\'s own `unit_system` (governing only that one series).'),
  "max_active_power": zod.number().describe('Maximum active power that this load can demand. Units: per power_units — NATURAL_UNITS: MW, COMPONENT_BASE: pu .'),
  "max_reactive_power": zod.number().describe('Maximum reactive power that this load can demand. Units: per power_units — NATURAL_UNITS: MVAr, COMPONENT_BASE: pu .'),
  "conformity": zod.enum(['NON_CONFORMING', 'CONFORMING', 'UNDEFINED']).optional().describe('WECC classification of how a load tracks voltage and frequency variation, used in dynamic studies to decide how it is modeled during a disturbance. `CONFORMING` responds predictably and follows standard load modeling practice; `NON_CONFORMING` does not, as with a constant power load or one behind a complex control system; `UNDEFINED` leaves the classification unstated.'),
  "dynamic_injector": zod.int().nullish().describe('ID of the corresponding dynamic injection device, if any.')
}).describe('A voltage-dependent ZIP load, most commonly used for dynamics modeling.\n\nAn `ExponentialLoad` models active power as P = P0 * V^α and reactive power as Q = Q0 * V^β, where the exponents α and β select govern the voltage dependency. For an alternative three-part formulation of the ZIP model, see `StandardLoad`. For a simpler load model with no voltage dependency, see `PowerLoad`.')

export type ExponentialLoad = zod.input<typeof ExponentialLoad>;
export type ExponentialLoadOutput = zod.output<typeof ExponentialLoad>;

export const fACTSControlDeviceMaxReactivePowerDefault = 9999;
export const fACTSControlDeviceShuntControlTypeDefault = `STATCOM`;
export const fACTSControlDeviceRegulatedBusNumberDefault = 0;
export const FACTSControlDevice = zod.object({
  "name": zod.string().describe('Name of the component. Components of the same type (e.g., `PowerLoad`) must have unique names, but components of different types (e.g., `PowerLoad` and `ACBus`) can have the same name.'),
  "id": zod.int().describe('Unique integer identifier for this component.'),
  "available": zod.boolean().describe('Indicator of whether the component is connected and online (`true`) or disconnected, offline, or down (`false`). Unavailable components are excluded during simulations.'),
  "bus": zod.int().describe('Sending end bus number.'),
  "control_mode": zod.enum(['OOS', 'NML', 'BYP']).optional().describe('Operating mode of a FACTS control device. `OOS` (out-of-service): both series and shunt links are open. `NML` (normal): both series and shunt links are operating. `BYP` (bypass): the series link is bypassed (acts as a zero-impedance line) and the shunt link operates as a STATCOM (reactive-only).'),
  "voltage_setpoint_units": zod.enum(['NATURAL_UNITS', 'COMPONENT_BASE']).optional().describe('Unit basis a voltage setpoint is stored in. NATURAL_UNITS: kilovolts. COMPONENT_BASE: per-unit on the component\'s own base voltage (the connected bus\'s base voltage for AC setpoints — PSS/E RAW native for FACTS VSET — and the device voltage base PSS/E supplies for DC-line converters and CZ=2 transformer windings). There is no separate system-base option: bus-base per-unit is the device base for voltage.'),
  "voltage_setpoint": zod.number().describe('Voltage setpoint at the sending end bus in kV, it has to be a `PV` bus. Units: kV. Units: per voltage_setpoint_units — NATURAL_UNITS: kV, COMPONENT_BASE: pu .'),
  "max_shunt_current": zod.number().describe('Maximum shunt current at the sending end bus; entered at unity voltage. Units: per power_units — NATURAL_UNITS: MVA, COMPONENT_BASE: pu .'),
  "reactive_power_required": zod.number().describe('Total reactive power required to hold voltage at sending bus, as a fraction in the range 0-1. Units: 1.'),
  "max_reactive_power": zod.number().default(fACTSControlDeviceMaxReactivePowerDefault).describe('Independent maximum reactive power ceiling; the device reactive limit is min(the current/susceptance law on max_shunt_current, this value). Non-binding at the 9999.0 default. Units: per power_units — NATURAL_UNITS: MVAr, COMPONENT_BASE: pu .'),
  "shunt_control_type": zod.enum(['SVC', 'STATCOM']).default(fACTSControlDeviceShuntControlTypeDefault).describe('Device class selecting the reactive-limit law (SVC vs STATCOM).'),
  "regulated_bus_number": zod.int().default(fACTSControlDeviceRegulatedBusNumberDefault).describe('Bus whose voltage this device regulates; 0 means local (sending) bus (PSS/E FCREG). Units: 1.'),
  "base_power": zod.number().describe('System base power for per-unitization of this component\'s per-unit fields, recorded per component in lieu of a system-level table. Units: MVA.'),
  "power_units": zod.enum(['COMPONENT_BASE', 'NATURAL_UNITS']).describe('Unit basis a stored value is expressed in. COMPONENT_BASE: per-unit against a base the component records itself. NATURAL_UNITS: the quantity\'s own physical unit. No system-wide option: a value per-unitized against a shared base records that base on the component and rides as COMPONENT_BASE. Used in three scopes, each read against its own record rather than a document-wide table: a component\'s own `power_units` (against that component\'s `base_power`), a cost payload\'s own `power_units` (e.g. `CostCurve`, against the owning component\'s `base_power`), and a time series association\'s own `unit_system` (governing only that one series).'),
  "dynamic_injector": zod.int().nullish().describe('ID of the corresponding dynamic injection model for FACTS control device, if any.')
}).describe('Facts control devices.\n\nMost often used in AC power flow studies as a control of voltage and, active and reactive power.')

export type FACTSControlDevice = zod.input<typeof FACTSControlDevice>;
export type FACTSControlDeviceOutput = zod.output<typeof FACTSControlDevice>;

export const FixedAdmittance = zod.object({
  "id": zod.int().describe('Unique integer identifier for this component.'),
  "name": zod.string().describe('Name of the component. Components of the same type (e.g., `PowerLoad`) must have unique names, but components of different types (e.g., `PowerLoad` and `ACBus`) can have the same name.'),
  "available": zod.boolean().describe('Indicator of whether the component is connected and online (`true`) or disconnected, offline, or down (`false`). Unavailable components are excluded during simulations.'),
  "bus": zod.int().describe('ID of the bus that this component is connected to.'),
  "admittance_units": zod.enum(['NATURAL_UNITS', 'COMPONENT_MVAR']).optional().describe('Subset of AdmittanceUnitBasis for fixed and switched shunts: omits COMPONENT_BASE because a shunt has no device MVA rating to per-unitize against. NATURAL_UNITS: physical siemens. COMPONENT_MVAR: reactive power at unity voltage (Mvar for susceptance, MW for conductance) — PSS/E RAW native for shunts.'),
  "Y": zod.object({
  "real": zod.number().optional(),
  "imag": zod.number().optional()
}).describe('A complex number, given as its `real` and `imag` parts.'),
  "base_power": zod.number().describe('System base power for per-unitization of this component\'s per-unit fields, recorded per component in lieu of a system-level table. Units: MVA.'),
  "dynamic_injector": zod.int().nullish().describe('ID of the corresponding dynamic injection model for admittance, if any.')
}).describe('A fixed admittance.\n\nMost often used in dynamics or AC power flow studies as a source of reactive power.')

export type FixedAdmittance = zod.input<typeof FixedAdmittance>;
export type FixedAdmittanceOutput = zod.output<typeof FixedAdmittance>;

export const fixedForcedOutageMonitoredComponentsDefault = [];
