export const GenericArcImpedance = zod.object({
  "id": zod.int().describe('Unique integer identifier for this component.'),
  "name": zod.string().describe('Name of the component. Components of the same type (e.g., `PowerLoad`) must have unique names, but components of different types (e.g., `PowerLoad` and `ACBus`) can have the same name.'),
  "available": zod.boolean().describe('Indicator of whether the component is connected and online (`true`) or disconnected, offline, or down (`false`). Unavailable components are excluded during simulations.'),
  "active_power_flow": zod.number().describe('Initial condition of active power flow on the line. Units: per power_units — NATURAL_UNITS: MW, COMPONENT_BASE: pu .'),
  "reactive_power_flow": zod.number().describe('Initial condition of reactive power flow on the line. Units: per power_units — NATURAL_UNITS: MVAr, COMPONENT_BASE: pu .'),
  "max_flow": zod.number().describe('Maximum allowable flow on the generic impedance. Units: per power_units — NATURAL_UNITS: MW, COMPONENT_BASE: pu .'),
  "arc": zod.int().describe('An `Arc` defining this line `from` a bus `to` another bus.'),
  "base_power": zod.number().describe('System base power for per-unitization of this component\'s per-unit fields, recorded per component in lieu of a system-level table. Units: MVA.'),
  "power_units": zod.enum(['COMPONENT_BASE', 'NATURAL_UNITS']).describe('Unit basis a stored value is expressed in. COMPONENT_BASE: per-unit against a base the component records itself. NATURAL_UNITS: the quantity\'s own physical unit. No system-wide option: a value per-unitized against a shared base records that base on the component and rides as COMPONENT_BASE. Used in three scopes, each read against its own record rather than a document-wide table: a component\'s own `power_units` (against that component\'s `base_power`), a cost payload\'s own `power_units` (e.g. `CostCurve`, against the owning component\'s `base_power`), and a time series association\'s own `unit_system` (governing only that one series).'),
  "parameter_units": zod.enum(['NATURAL_UNITS', 'COMPONENT_BASE']).optional().describe('Unit basis a branch/injection impedance is stored in. NATURAL_UNITS: physical ohms (PSS/E RAW native for DC-line impedances). COMPONENT_BASE: per-unit on the component\'s own base (base_power MVA and voltage base); components whose per-unit data was historically on the system base record that system base in base_power, so there is no separate system-base option. PSS/E supplies device base for DC-line converters and CZ=2 transformer windings. A branch\'s shunt admittance halves (b, g) share the branch\'s one basis: NATURAL_UNITS stores them in siemens.'),
  "r": zod.number().describe('Resistance. Units: per parameter_units — NATURAL_UNITS: ohm, COMPONENT_BASE: pu .'),
  "x": zod.number().describe('Reactance. Units: per parameter_units — NATURAL_UNITS: ohm, COMPONENT_BASE: pu .')
}).describe('A generic branch defined by a series impedance on an `Arc` between two buses.')

export type GenericArcImpedance = zod.input<typeof GenericArcImpedance>;
export type GenericArcImpedanceOutput = zod.output<typeof GenericArcImpedance>;

