export const standardLoadConstantActivePowerDefault = 0;
export const standardLoadConstantReactivePowerDefault = 0;
export const standardLoadImpedanceActivePowerDefault = 0;
export const standardLoadImpedanceReactivePowerDefault = 0;
export const standardLoadCurrentActivePowerDefault = 0;
export const standardLoadCurrentReactivePowerDefault = 0;
export const standardLoadMaxConstantActivePowerDefault = 0;
export const standardLoadMaxConstantReactivePowerDefault = 0;
export const standardLoadMaxImpedanceActivePowerDefault = 0;
export const standardLoadMaxImpedanceReactivePowerDefault = 0;
export const standardLoadMaxCurrentActivePowerDefault = 0;
export const standardLoadMaxCurrentReactivePowerDefault = 0;
export const StandardLoad = zod.object({
  "id": zod.int().describe('Unique integer identifier for this component.'),
  "name": zod.string().describe('Name of the component. Components of the same type (e.g., `PowerLoad`) must have unique names, but components of different types (e.g., `PowerLoad` and `ACBus`) can have the same name.'),
  "available": zod.boolean().describe('Indicator of whether the component is connected and online (`true`) or disconnected, offline, or down (`false`). Unavailable components are excluded during simulations.'),
  "bus": zod.int().describe('ID of the bus that this component is connected to.'),
  "base_power": zod.number().describe('Base power of the load for per unitization. Units: MVA.'),
  "power_units": zod.enum(['COMPONENT_BASE', 'NATURAL_UNITS']).describe('Unit basis a stored value is expressed in. COMPONENT_BASE: per-unit against a base the component records itself. NATURAL_UNITS: the quantity\'s own physical unit. No system-wide option: a value per-unitized against a shared base records that base on the component and rides as COMPONENT_BASE. Used in three scopes, each read against its own record rather than a document-wide table: a component\'s own `power_units` (against that component\'s `base_power`), a cost payload\'s own `power_units` (e.g. `CostCurve`, against the owning component\'s `base_power`), and a time series association\'s own `unit_system` (governing only that one series).'),
  "constant_active_power": zod.number().default(standardLoadConstantActivePowerDefault).describe('Constant active power demand (P_P). Units: per power_units — NATURAL_UNITS: MW, COMPONENT_BASE: pu .'),
  "constant_reactive_power": zod.number().default(standardLoadConstantReactivePowerDefault).describe('Constant reactive power demand (Q_P). Units: per power_units — NATURAL_UNITS: MVAr, COMPONENT_BASE: pu .'),
  "impedance_active_power": zod.number().default(standardLoadImpedanceActivePowerDefault).describe('Active power coefficient for constant impedance load (P_Z). Units: per power_units — NATURAL_UNITS: MW, COMPONENT_BASE: pu .'),
  "impedance_reactive_power": zod.number().default(standardLoadImpedanceReactivePowerDefault).describe('Reactive power coefficient for constant impedance load (Q_Z). Units: per power_units — NATURAL_UNITS: MVAr, COMPONENT_BASE: pu .'),
  "current_active_power": zod.number().default(standardLoadCurrentActivePowerDefault).describe('Active power coefficient for constant current load (P_I). Units: per power_units — NATURAL_UNITS: MW, COMPONENT_BASE: pu .'),
  "current_reactive_power": zod.number().default(standardLoadCurrentReactivePowerDefault).describe('Reactive power coefficient for constant current load (Q_I). Units: per power_units — NATURAL_UNITS: MVAr, COMPONENT_BASE: pu .'),
  "max_constant_active_power": zod.number().default(standardLoadMaxConstantActivePowerDefault).describe('Maximum active power drawn by constant power load. Units: per power_units — NATURAL_UNITS: MW, COMPONENT_BASE: pu .'),
  "max_constant_reactive_power": zod.number().default(standardLoadMaxConstantReactivePowerDefault).describe('Maximum reactive power drawn by constant power load. Units: per power_units — NATURAL_UNITS: MVAr, COMPONENT_BASE: pu .'),
  "max_impedance_active_power": zod.number().default(standardLoadMaxImpedanceActivePowerDefault).describe('Maximum active power drawn by constant impedance load. Units: per power_units — NATURAL_UNITS: MW, COMPONENT_BASE: pu .'),
  "max_impedance_reactive_power": zod.number().default(standardLoadMaxImpedanceReactivePowerDefault).describe('Maximum reactive power drawn by constant impedance load. Units: per power_units — NATURAL_UNITS: MVAr, COMPONENT_BASE: pu .'),
  "max_current_active_power": zod.number().default(standardLoadMaxCurrentActivePowerDefault).describe('Maximum active power drawn by constant current load. Units: per power_units — NATURAL_UNITS: MW, COMPONENT_BASE: pu .'),
  "max_current_reactive_power": zod.number().default(standardLoadMaxCurrentReactivePowerDefault).describe('Maximum reactive power drawn by constant current load. Units: per power_units — NATURAL_UNITS: MVAr, COMPONENT_BASE: pu .'),
  "conformity": zod.enum(['NON_CONFORMING', 'CONFORMING', 'UNDEFINED']).optional().describe('WECC classification of how a load tracks voltage and frequency variation, used in dynamic studies to decide how it is modeled during a disturbance. `CONFORMING` responds predictably and follows standard load modeling practice; `NON_CONFORMING` does not, as with a constant power load or one behind a complex control system; `UNDEFINED` leaves the classification unstated.'),
  "dynamic_injector": zod.int().nullish().describe('ID of the corresponding dynamic injection device, if any.')
}).describe('A voltage-dependent ZIP load, most commonly used for dynamics modeling.\n\nA `StandardLoad` breaks the ZIP into three pieces: Z (constant impedance), I (constant current), and P (constant power), according to `P = P_P * V^0 + P_I * V^1 + P_Z * V^2` for active power and `Q = Q_P * V^0 + Q_I * V^1 + Q_Z * V^2` for reactive power. (Voltage V is in per unit.)\n\nFor an alternative exponential formulation of the ZIP model, see `ExponentialLoad`. For a simpler load model with no voltage dependency, see `PowerLoad`.')

export type StandardLoad = zod.input<typeof StandardLoad>;
export type StandardLoadOutput = zod.output<typeof StandardLoad>;

export const substationGroundingResistanceDefault = 0.1;
export const Substation = zod.object({
  "id": zod.int(),
  "name": zod.string().describe('Name of the substation'),
  "number": zod.int().describe('Substation number in the source power flow data'),
  "grounding_resistance": zod.number().default(substationGroundingResistanceDefault).describe('Substation grounding DC resistance. Units: ohm.')
}).describe('Supplemental attribute representing a substation that groups node buses and switching devices of a full-topology (node-breaker) network model. Attach the attribute to every member component. Geospatial data is not stored here; attach a GeographicInfo attribute to the member components instead.')

