export type SubstationOutput = zod.output<typeof Substation>;

export const switchedAdmittanceRegulatedBusNumberDefault = 0;
export const SwitchedAdmittance = zod.object({
  "id": zod.int().describe('Unique integer identifier for this component.'),
  "name": zod.string().describe('Name of the component. Components of the same type (e.g., `PowerLoad`) must have unique names, but components of different types (e.g., `PowerLoad` and `ACBus`) can have the same name.'),
  "available": zod.boolean().describe('Indicator of whether the component is connected and online (`true`) or disconnected, offline, or down (`false`). Unavailable components are excluded during simulations.'),
  "bus": zod.int().describe('ID of the bus that this component is connected to.'),
  "admittance_units": zod.enum(['NATURAL_UNITS', 'COMPONENT_MVAR']).optional().describe('Subset of AdmittanceUnitBasis for fixed and switched shunts: omits COMPONENT_BASE because a shunt has no device MVA rating to per-unitize against. NATURAL_UNITS: physical siemens. COMPONENT_MVAR: reactive power at unity voltage (Mvar for susceptance, MW for conductance) — PSS/E RAW native for shunts.'),
  "number_engaged": zod.array(zod.int()).optional().describe('Vector with the number of steps currently engaged (switched in) for each adjustable shunt block. For example, `number_engaged[2]` is the number of steps in service at block 2, and cannot exceed `number_of_steps[2]`.'),
  "number_of_steps": zod.array(zod.int()).optional().describe('Vector with number of steps for each adjustable shunt block. For example, `number_of_steps[2]` are the number of available steps for admittance increment at block 2.'),
  "Y_increase": zod.array(zod.object({
  "real": zod.number().optional(),
  "imag": zod.number().optional()
}).describe('A complex number, given as its `real` and `imag` parts.')).optional().describe('Vector with admittance increment step for each adjustable shunt block. For example, `Y_increase[2]` is the complex admittance increment for each step at block 2. Units: per admittance_units — NATURAL_UNITS: S, COMPONENT_MVAR: MVAr .'),
  "solved_admittance": zod.number().nullish().describe('Solved-case switched shunt admittance (PSS/E BINIT); when present it is the shunt\'s effective admittance, used in place of `number_engaged` * `Y_increase`. Units: per admittance_units — NATURAL_UNITS: S, COMPONENT_MVAR: MVAr .'),
  "admittance_limits": zod.object({
  "max": zod.number().optional(),
  "min": zod.number().optional()
}).optional().describe('A pair of values bounding a quantity from below (`min`) and from above (`max`).'),
  "control_mode": zod.enum(['UNDEFINED', 'FIXED', 'DISCRETE_VOLTAGE', 'CONTINUOUS_VOLTAGE', 'DISCRETE_REACTIVE_PLANT', 'DISCRETE_REACTIVE_VSC', 'DISCRETE_ADMITTANCE_REMOTE']).optional().describe('Control mode of a switched shunt admittance. `UNDEFINED` leaves the mode unspecified; `FIXED` holds the admittance at a constant value; `CONTINUOUS_VOLTAGE` adjusts it continuously to control voltage. The `DISCRETE_*` modes switch blocks in discrete steps to control voltage, a plant\'s reactive power, a voltage-source-converter terminal\'s reactive power, or a remote bus\'s admittance, respectively.'),
  "regulated_bus_number": zod.int().default(switchedAdmittanceRegulatedBusNumberDefault).describe('Bus number whose voltage/quantity this shunt regulates; 0 means local bus (PSS/E SWREM/NREG). Units: 1.'),
  "dynamic_injector": zod.int().nullish().describe('ID of the corresponding dynamic injection model for admittance, if any.')
}).describe('A switched admittance, with discrete steps to adjust the admittance.\n\nMost often used in power flow studies, iterating over the steps to see impacts of admittance on the results. Total admittance is `number_engaged` * `Y_increase`, unless `solved_admittance` is set, in which case that value is the effective admittance. There is no fixed base admittance: a PSS/E SWITCHED SHUNT record carries only BINIT and the per-block increments.')

export type SwitchedAdmittance = zod.input<typeof SwitchedAdmittance>;
export type SwitchedAdmittanceOutput = zod.output<typeof SwitchedAdmittance>;

