export type TwoTerminalVSCLine = zod.input<typeof TwoTerminalVSCLine>;
export type TwoTerminalVSCLineOutput = zod.output<typeof TwoTerminalVSCLine>;

export const TwoWindingTransformer = zod.object({
  "id": zod.int().describe('Unique integer identifier for this component.'),
  "name": zod.string().describe('Name of the component. Components of the same type (e.g., `PowerLoad`) must have unique names, but components of different types (e.g., `PowerLoad` and `ACBus`) can have the same name.'),
  "circuit": zod.int().describe('The `TransformerCircuit` carrying this transformer\'s series electrical data.'),
  "admittance_units": zod.enum(['NATURAL_UNITS', 'COMPONENT_MVAR', 'COMPONENT_BASE']).optional().describe('Unit basis a shunt admittance is stored in. NATURAL_UNITS: physical siemens. COMPONENT_MVAR: reactive power at unity voltage (Mvar for susceptance, MW for conductance). COMPONENT_BASE: per-unit on the component\'s own base (base_power MVA and voltage base) — a per-unit base, not a power at unity voltage, and not an alternative spelling of COMPONENT_MVAR; components whose per-unit data was historically on the system base record that system base in base_power. Fixed and switched shunts use ShuntAdmittanceUnitBasis instead, which omits COMPONENT_BASE because a shunt has no device MVA rating.'),
  "magnetizing_shunt": zod.object({
  "real": zod.number().optional(),
  "imag": zod.number().optional()
}).optional().describe('A complex number, given as its `real` and `imag` parts.'),
  "shunt_location": zod.enum(['PRIMARY', 'SECONDARY', 'SPLIT']).optional().describe('Placement of a `TwoWindingTransformer`\'s magnetizing shunt admittance on the two sides of its single circuit arc. PRIMARY: the full magnetizing shunt is applied on the primary (from) side. SECONDARY: the full magnetizing shunt is applied on the secondary (to) side. SPLIT: the full complex magnetizing shunt value is applied on BOTH sides.')
}).describe('A two-winding transformer connecting two buses.\n\nAll series electrical data — the modeled arc, tap, phase shift, series impedance `r`/`x`, ratings, per-winding base power, base voltages, and control — lives on the single `TransformerCircuit` referenced by `circuit`; availability is circuit-level. The `magnetizing_shunt` admittance and its `shunt_location` are transformer-level. The model uses an equivalent circuit assuming the impedance is on the high-voltage side and allocates iron losses and magnetizing susceptance according to `shunt_location`. The transformer\'s device base is the circuit\'s `base_power`.')

export type TwoWindingTransformer = zod.input<typeof TwoWindingTransformer>;
export type TwoWindingTransformerOutput = zod.output<typeof TwoWindingTransformer>;

