export const VSCACControlModes = zod.enum(['AC_REACTIVE_POWER', 'AC_VOLTAGE']).describe('AC-side control mode of a voltage-source-converter (VSC) terminal. AC_REACTIVE_POWER: converter controls reactive power / fixed power factor. AC_VOLTAGE: converter controls the AC-side voltage magnitude.')

