export const CurveMultiStepDefault = 0;
export const CurveMultiStep = zod.union([zod.literal(0),zod.literal(1)]).default(CurveMultiStepDefault).describe('Multi-step block indicator for a bid: 0 = SINGLE_STEP (default; each step of the bid clears independently); 1 = MULTI_STEP (the bid must be awarded as one block across every step it covers). Counted in model steps so it applies at any resolution. Independent of curve style: curve style is the quantity structure, this is the time structure, and they compose.')

export type CurveMultiStep = zod.input<typeof CurveMultiStep>;
export type CurveMultiStepOutput = zod.output<typeof CurveMultiStep>;

export const CurveStylesDefault = 0;
export const CurveStyles = zod.union([zod.literal(0),zod.literal(1)]).default(CurveStylesDefault).describe('Curve-clearing style for a bid: 0 = VARIABLE (default; continuous quantity with one or more segments); 1 = FIXED (all-or-nothing block with a single segment). FIXED is mutually exclusive with incremental_slope/decremental_slope and requires a single-segment offer curve.')

export type CurveStyles = zod.input<typeof CurveStyles>;
export type CurveStylesOutput = zod.output<typeof CurveStyles>;

export const EnergyUnitBasis = zod.enum(['MWH', 'MWMIN']).describe('Unit basis a stored-energy quantity is recorded in (distinct from EnergyUnit, which names fuel energy content). MWH: megawatt-hours, the conventional interchange form. MWMIN: megawatt-minutes, consistent with the minutes basis used for operational durations, so a duration computed as energy over power comes out in minutes with no hidden factor of 60. Defaults to MWH: MWMIN is supported, not preferred.')

export type EnergyUnitBasis = zod.input<typeof EnergyUnitBasis>;
export type EnergyUnitBasisOutput = zod.output<typeof EnergyUnitBasis>;

export const FromTo = zod.object({
  "from": zod.number().optional(),
  "to": zod.number().optional()
}).describe('A pair of values, one at the `from` end and one at the `to` end of a directed edge.')

export type FromTo = zod.input<typeof FromTo>;
export type FromToOutput = zod.output<typeof FromTo>;

export const FromToToFrom = zod.object({
  "from_to": zod.number().optional(),
  "to_from": zod.number().optional()
}).describe('A pair of values for a directed edge, one for each orientation: `from_to` and `to_from`. The two are carried separately because the quantity need not be equal in the two directions.')

export type FromToToFrom = zod.input<typeof FromToToFrom>;
export type FromToToFromOutput = zod.output<typeof FromToToFrom>;

